def _d(title, summary, intro, note, labels, sections, closing_h, closing, links):
    """labels: (шаги, хорошо/тревожно, подробнее); sections: 14 × (заголовок, смысл, [шаги], подпись картинки, [признаки])."""
    body = [("p", intro), ("note", note)]
    for key, (h, meaning, steps, cap, signs) in zip(ANCHORS, sections):
        body += [("h", h, key), ("p", meaning), ("ol", steps), ("svg", key, cap), ("ul", signs)]
        if REFS[key]:
            body.append(("refs", labels[2], REFS[key]))
    body += [("h", closing_h), ("p", closing), ("links", links)]
    return {"title": title, "summary": summary, "body": body}


